from fractions import Fraction
from decimal import Decimal

def solve(facts):
    def rounded(x):
        sign = -1 if x < 0 else 1
        n, d = abs(x.numerator), x.denominator
        return sign * ((2 * n + d) // (2 * d))
    subtotal = sum(rounded(Fraction(str(line['qty'])) * Fraction(str(line['unit_cents'])) * (1 - Fraction(line['discount_percent']) / 100)) for line in facts['lines'])
    tax = rounded(subtotal * Fraction(facts['tax_percent']) / 100)
    return {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + int(facts['shipping'])}

def check(answer, facts):
    def ratio(value):
        t = Decimal(str(value)).as_tuple()
        n = 0
        for digit in t.digits:
            n = n * 10 + digit
        if t.sign:
            n = -n
        if t.exponent >= 0:
            return n * 10 ** t.exponent, 1
        return n, 10 ** (-t.exponent)
    def rounded(n, d):
        q, r = divmod(abs(n), d)
        if r * 2 >= d:
            q += 1
        return -q if n < 0 else q
    if not isinstance(answer, dict) or set(answer) != {'subtotal_cents', 'tax_cents', 'total_cents'}:
        return False
    if not all(isinstance(v, int) and not isinstance(v, bool) for v in answer.values()):
        return False
    subtotal = 0
    for line in facts['lines']:
        qn, qd = ratio(line['qty'])
        un, ud = ratio(line['unit_cents'])
        dn, dd = ratio(line['discount_percent'])
        subtotal += rounded(qn * un * (100 * dd - dn), qd * ud * 100 * dd)
    tn, td = ratio(facts['tax_percent'])
    tax = rounded(subtotal * tn, 100 * td)
    return answer['subtotal_cents'] == subtotal and answer['tax_cents'] == tax and answer['total_cents'] == subtotal + tax + int(facts['shipping'])
